on conflict (wikidata_qid) where wikidata_qid is not null do update
  set tmdb_id           = excluded.tmdb_id,
      title             = excluded.title,
      release_date      = excluded.release_date,
      runtime_minutes   = excluded.runtime_minutes,
      original_language = excluded.original_language,
      genres            = excluded.genres,
      fetched_at        = now()
  where media_items.provenance = 'wikidata';

-- Series are watchlistable but never loggable or rankable (PRD §10): the season is
-- the unit, and "I watched this series" cannot say which seasons.
-- Series
insert into media_items (kind, tmdb_id, wikidata_qid, title, release_date,
                         runtime_minutes, original_language, genres, provenance)
