on conflict (wikidata_qid) where wikidata_qid is not null do update
  set tmdb_id           = excluded.tmdb_id,
      title             = excluded.title,
      release_date      = excluded.release_date,
      runtime_minutes   = excluded.runtime_minutes,
      original_language = excluded.original_language,
      genres            = excluded.genres,
      fetched_at        = now()
  where media_items.provenance = 'wikidata';

-- Seasons. The parent is joined by its Wikidata id rather than named by a literal
-- uuid, because ids are generated at insert time and a refresh has to land on the
-- same row. A season whose parent is absent contributes nothing rather than failing:
-- the join drops it.
--
-- Seasons carry their own Wikidata id too. Without it a season would be identified
-- only by its parent and its number, which means nothing outside this catalogue
-- could match it — and seasons are the rankable television unit (PRD §10), so that
-- would leave most of the TV half of the product unmatched when the adapter lands.
--
-- Keyed on (parent_id, season_number) rather than on the Wikidata id, unlike the
-- films above: a season number is the more stable of the two here, since Wikidata
-- season items are split and merged more often than a series is renumbered.
insert into media_items (kind, parent_id, season_number, wikidata_qid, title,
                         release_date, provenance)
select 'season', parent.id, seed.season_number, seed.wikidata_qid, seed.title,
       seed.release_date, 'wikidata'
  from (values
    ('Q105553568', 1, 'Q115427742', $seed$Season 1$seed$, '2022-11-23'::date),
    ('Q105553568', 2, 'Q116629020', $seed$Season 2$seed$, '2025-08-06'::date),
    ('Q105553568', 3, 'Q135652834', $seed$Season 3$seed$, null::date),
    ('Q106582931', 1, 'Q108806773', $seed$Season 1$seed$, '2021-09-17'::date),
    ('Q106582931', 2, 'Q112431753', $seed$Season 2$seed$, '2024-12-26'::date),
    ('Q106582931', 3, 'Q128239752', $seed$Season 3$seed$, '2025-06-27'::date),
    ('Q1077', 1, 'Q747598', $seed$Season 1$seed$, '1966-09-07'::date),
    ('Q1077', 2, 'Q3468578', $seed$Season 2$seed$, '1967-09-14'::date),
    ('Q1077', 3, 'Q3468783', $seed$Season 3$seed$, '1968-09-19'::date),
    ('Q1079', 1, 'Q1582890', $seed$Season 1$seed$, '2008-01-20'::date),
